require_once __DIR__.'/../includes/verificar_sesion.php';$roles_permitidos=['administrador'];require_once __DIR__.'/../includes/verificar_rol.php';require_once __DIR__.'/../config/conexion.php';$estado=$_GET['estado']??'';$sql='SELECT s.*,u.nombre AS cliente,c.estado AS estado_cotizacion FROM solicitudes s JOIN usuarios u ON u.id_usuario=s.id_cliente LEFT JOIN cotizaciones c ON c.id_solicitud=s.id_solicitud';$param=[];if($estado!==''){$sql.=' WHERE s.estado=?';$param[]=$estado;}$sql.=' ORDER BY s.fecha_solicitud DESC';$q=$pdo->prepare($sql);$q->execute($param);$solicitudes=$q->fetchAll();$titulo_pagina='Solicitudes';$ruta_base='../';require_once __DIR__.'/../includes/encabezado.php';
?><div class="cabecera-panel"><div><span class="etiqueta">OPERACIÓN</span><h1>Solicitudes</h1><p>Revisa cada petición y prepara una cotización.</p></div></div><form class="filtros" method="get"><label>Filtrar por estado<select name="estado"><option value="">Todos</option><?php foreach(['Pendiente','En revisión','Cotizada','Aceptada','Rechazada','En reparación','Terminada'] as $op): ?><option <?= $estado===$op?'selected':'' ?>><?= $op ?></option><?php endforeach; ?></select></label><button class="boton boton-secundario" type="submit">Aplicar</button></form><section class="tabla-contenedor"><table class="tabla"><thead><tr><th>ID</th><th>Cliente</th><th>Consola</th><th>Problema</th><th>Estado</th><th>Cotización</th><th>Fecha</th><th></th></tr></thead><tbody><?php if(!$solicitudes): ?><tr><td colspan="8" class="vacio">No hay solicitudes con este filtro.</td></tr><?php else: foreach($solicitudes as $s): ?><tr><td>#<?= $s['id_solicitud'] ?></td><td><?= escapar($s['cliente']) ?></td><td><?= escapar($s['marca'].' '.$s['modelo']) ?></td><td><?= escapar($s['problema_reportado']) ?></td><td><span class="<?= estado_clase($s['estado']) ?>"><?= escapar($s['estado']) ?></span></td><td><?= escapar($s['estado_cotizacion']??'Sin cotizar') ?></td><td><?= date('d/m/Y',strtotime($s['fecha_solicitud'])) ?></td><td><a class="enlace" href="detalle_solicitud.php?id=<?= $s['id_solicitud'] ?>">Gestionar →</a></td></tr><?php endforeach; endif; ?></tbody></table></section><?php require_once __DIR__.'/../includes/pie.php'; ?>

